import {worldCacheRead,worldCacheWrite} from './world-weather.js';
import {esc,weatherKind,weatherName,valueText} from './weather-tools.js';
import {HAIL_SIZE_LABELS} from './hail-tools.js';

export const GLOBE_FILTERS=[['all','Tutti i fenomeni'],['weather','Meteo'],['rain','Pioggia e neve'],['wind','Vento'],['cloud','Nuvole'],['hail','Grandine segnalata'],['event','Eventi naturali'],['alert','Allerte della zona']];
const num=v=>typeof v==='number'&&Number.isFinite(v);
export const validPosition=p=>p&&num(p.latitude)&&num(p.longitude)&&Math.abs(p.latitude)<=90&&Math.abs(p.longitude)<=180;
const fresh=(at,now,age)=>num(at)&&at<=now+600000&&at>=now-age;
export function windArrow(deg){return num(deg)?['↑','↗','→','↘','↓','↙','←','↖'][Math.round((((deg+180)%360)+360)%360/45)%8]:'↝'}
export function modelTime(time,offset=0){return typeof time==='string'&&num(offset)?Date.parse(time+(time.endsWith('Z')?'':'Z'))-offset*1000:NaN}
export function weatherRecord(city,now=Date.now(),offset=0){
 const w=city?.current,at=modelTime(w?.time,offset);if(!validPosition(city)||!w||!num(w.temperature_2m)||!num(w.weather_code)||!fresh(at,now,10800000))return null;
 const kind=weatherKind(w.weather_code,w.is_day!==0),icon={sun:'☀',moon:'☾',partly:'⛅',cloud:'☁',snow:'❄',storm:'ϟ',rain:'☂',unknown:'?'}[kind];
 return {id:'weather:'+String(city.id||'local'),category:'weather',name:String(city.name||'Zona selezionata').slice(0,90),latitude:city.latitude,longitude:city.longitude,at,icon,color:{sun:'#ffcc50',moon:'#c6cef8',partly:'#daeafa',cloud:'#c8d5e5',snow:'#b7ecff',storm:'#d6b2ff',rain:'#80cfff',unknown:'#ddd'}[kind],value:Math.round(w.temperature_2m)+'°',detail:weatherName(w.weather_code),source:'Open-Meteo · modello',current:w,kind};
}
export function hailRecords(data,now=Date.now()){
 if(!Array.isArray(data?.posts)||!fresh(data.updated,now,90000))return [];
 return data.posts.slice(0,500).flatMap(p=>{const at=p.observed||p.created;
  if(!/^[\w-]{1,80}$/.test(p.id||'')||!Number.isInteger(p.map_lat)||!Number.isInteger(p.map_lon)||Math.abs(p.map_lat)>8500||Math.abs(p.map_lon)>18000||!fresh(at,now,7200000)||p.ended||p.expires&&p.expires<=now)return [];
  return [{id:'hail:'+p.id,postId:p.id,category:'hail',name:String(p.city||'Zona segnalata').slice(0,90),latitude:p.map_lat/100,longitude:p.map_lon/100,at,icon:'●',color:'#e0bdff',value:'Grandine',detail:(HAIL_SIZE_LABELS[p.size]||HAIL_SIZE_LABELS.unknown)+' · '+(p.disputes>p.confirms?'Riscontri discordanti':'Segnalazione da verificare'),source:'Community · posizione approssimata',confirms:p.confirms||0,disputes:p.disputes||0}];
 });
}
export function eventRecords(data,now=Date.now()){if(!Array.isArray(data?.events)||!fresh(data.updated,now,86400000))return [];return data.events.filter(e=>validPosition(e)&&num(e.at)&&e.at<=now+600000).map(e=>({...e,catalogAt:Number.isFinite(e.catalogAt)?e.catalogAt:data.updated,id:'event:'+e.id,category:'event',stale:!!data.stale||now-data.updated>1800000,source:'NASA EONET · catalogo eventi aperti'}))}
export function validSource(kind,value){return !!value&&(kind==='cities'?Array.isArray(value.cities):kind==='hail'?Array.isArray(value.posts)&&num(value.updated):kind==='events'?Array.isArray(value.events)&&num(value.updated):kind==='safety'?typeof value.mode==='string'&&num(value.checkedAt):false)}
export function alertRecord(data,place,now=Date.now()){if(!validPosition(place)||!fresh(data?.checkedAt,now,900000)||![1,2,3].includes(data.level)||!data.validDate)return null;return {id:'alert:local',category:'alert',name:place.name,latitude:place.latitude,longitude:place.longitude,at:data.checkedAt,icon:'!',color:['','#ffe070','#ffaf68','#ff9696'][data.level],value:'Allerta '+['','gialla','arancione','rossa'][data.level],detail:'Bollettino valido il '+data.validDate+'. '+data.detail,source:'Protezione Civile · rischio previsto',link:data.source}}
export function filteredRecords(records,filter){return records.filter(r=>filter==='all'||filter==='weather'&&r.category==='weather'||filter==='rain'&&r.category==='weather'&&(r.current.precipitation>0||r.current.snowfall>0)||filter==='wind'&&r.category==='weather'&&num(r.current.wind_speed_10m)||filter==='cloud'&&r.category==='weather'&&num(r.current.cloud_cover)||r.category===filter)}
export function markerPayload(records,filter){return records.map(r=>{
 let label=r.value,icon=r.icon;
 if(r.category==='weather'){
  const w=r.current;if(filter==='wind'){icon=windArrow(w.wind_direction_10m);label=valueText(w.wind_speed_10m,' km/h')}
  else if(filter==='cloud'){icon='☁';label=valueText(w.cloud_cover,'%')}
  else if(filter==='rain'){icon=w.snowfall>0?'❄':'☂';label=w.snowfall>0?valueText(w.snowfall,' cm'):valueText(w.precipitation,' mm')}
  else if(num(w.wind_speed_10m))label+=' · '+windArrow(w.wind_direction_10m)+' '+Math.round(w.wind_speed_10m)+' km/h';
 }
 return {id:r.id,latitude:r.latitude,longitude:r.longitude,icon,label:icon+' '+label+' · '+r.name,color:r.color,priority:r.category==='alert'?5:r.category==='hail'?4:r.category==='event'?3:1};
})}
export function conditionDetail(r){if(!r)return '<p>Tocca un simbolo sul globo per vedere valori, fonte e orario.</p>';const w=r.current;
 return `<h3>${esc(r.icon)} ${esc(r.name)}</h3><p><strong>${esc(r.value)}</strong> · ${esc(r.detail)}</p>${w?`<dl class="globe-condition-values"><div><dt>Precipitazioni</dt><dd>${valueText(w.precipitation,' mm')}</dd></div><div><dt>Neve</dt><dd>${valueText(w.snowfall,' cm')}</dd></div><div><dt>Vento</dt><dd>${windArrow(w.wind_direction_10m)} ${valueText(w.wind_speed_10m,' km/h')}</dd></div><div><dt>Raffiche</dt><dd>${valueText(w.wind_gusts_10m,' km/h')}</dd></div><div><dt>Nuvole</dt><dd>${valueText(w.cloud_cover,'%')}</dd></div></dl><p>Quantità di precipitazioni nell’intervallo della fonte. Freccia: direzione verso cui soffia il vento.</p>`:''}<p class="google-meta">${esc(r.source)}<br>${new Date(r.at).toLocaleString('it-IT',{timeZone:'UTC'})} UTC${r.category==='alert'?' · controllo del bollettino':''}</p>${r.category==='event'&&Number.isFinite(r.started)?`<p>Prima data nel catalogo: ${new Date(r.started).toLocaleDateString('it-IT')}. Non certifica l’inizio effettivo dell’evento.</p>`:''}${r.category==='event'?'<p>“Aperto” è lo stato del catalogo: non conferma che l’evento stia avvenendo proprio adesso.</p>':''}${r.category==='hail'?`<p>${r.confirms} conferme · ${r.disputes} riscontri contrari</p><a href="#post:${esc(r.postId)}">Leggi la segnalazione</a>`:''}${r.link&&/^https:\/\//.test(r.link)?`<a href="${esc(r.link)}" target="_blank" rel="noopener">Apri la fonte</a>`:''}`;
}

export function createGlobeConditions(ctx){
 let active=false,run=0,filter='all',selected=null,timer=0,busy=false,lastModel=0,lastEvents=0,lastSafety=0,lastPlace='',data={cities:null,hail:null,events:null,safety:null},errors={};
 const $=s=>document.querySelector(s);
 function localKey(){const p=ctx.get().place;return p.latitude+','+p.longitude}
 function records(){const now=Date.now(),{place,weather}=ctx.get();let rows=(data.cities?.cities||[]).map(c=>weatherRecord(c,now)).filter(Boolean).map(r=>({...r,stale:!!errors.cities||!!data.cities?.stale}));const local=weatherRecord({...place,id:'local',current:weather?.current},now,weather?.utc_offset_seconds||0);if(local){rows=rows.filter(r=>Math.abs(r.latitude-local.latitude)+Math.abs(r.longitude-local.longitude)>.02);rows.unshift(local)}rows.push(...hailRecords(data.hail,now),...eventRecords(data.events,now));const warning=alertRecord(data.safety,place,now);if(warning)rows.push(warning);return rows}
 function controls(){return `<section class="globe-conditions-tools" aria-label="Fenomeni sul globo"><label>Fenomeni visibili<select id="globe-condition-filter">${GLOBE_FILTERS.map(([id,label])=>`<option value="${id}" ${filter===id?'selected':''}>${label}</option>`).join('')}</select></label><button data-conditions-refresh>Aggiorna dati</button><div class="globe-condition-legend"><span>☂ Pioggia</span><span>❄ Neve</span><span>☁ Nuvole</span><span>↗ Vento</span><span>● Grandine</span><span>! Allerta</span></div><p id="globe-conditions-status" role="status">Apri il globo: i simboli meteo verranno caricati sulla Terra.</p><p class="globe-data-note">Meteo: campioni del modello nelle città e nel punto scelto. Grandine: osservazioni delle persone. Eventi: catalogo NASA. Le zone vuote non indicano assenza di fenomeni.</p></section>`}
 function panel(){return '<section class="globe-condition-card"><h2>Fenomeni sulla Terra</h2><div id="globe-condition-detail">'+conditionDetail(null)+'</div><details><summary id="globe-condition-count">Elenco dei punti</summary><div id="globe-condition-list" class="globe-condition-list"></div></details><p id="globe-source-state"></p><a href="#radar">Apri il radar animato delle precipitazioni</a></section>'}
 function choose(id){const r=records().find(r=>r.id===id);if(!r)return;selected=id;const slot=$('#globe-condition-detail');if(slot)slot.innerHTML=conditionDetail(r);ctx.focus?.(r);}
 function paint(){if(!active)return;const all=records(),rows=filteredRecords(all,filter);if(!rows.some(r=>r.id===selected))selected=rows[0]?.id||null;ctx.send(markerPayload(rows,filter));ctx.onRecords?.(rows,{updated:data.cities?.updated,eventUpdated:data.events?.updated,stale:!!errors.cities||!!data.cities?.stale,eventsStale:!!errors.events||!!data.events?.stale});
  const status=$('#globe-conditions-status');if(status)status.textContent=rows.length?rows.length+' punti disponibili · avvicinati per separare i simboli. I valori indicano l’orario della fonte.':busy?'Caricamento dei fenomeni…':'Nessun dato disponibile per questo filtro. Non significa che non ci siano fenomeni.';
  const detail=$('#globe-condition-detail');if(detail)detail.innerHTML=conditionDetail(rows.find(r=>r.id===selected));const count=$('#globe-condition-count');if(count)count.textContent='Tutti i punti disponibili ('+rows.length+')';
  const list=$('#globe-condition-list');if(list){list.innerHTML=rows.map(r=>`<button data-condition-id="${esc(r.id)}"><span>${esc(r.icon)} ${esc(r.name)}</span><strong>${esc(r.value)}</strong><small>${esc(r.source)}</small></button>`).join('');list.querySelectorAll('[data-condition-id]').forEach(b=>b.onclick=()=>choose(b.dataset.conditionId))}
  const sources=$('#globe-source-state');if(sources){const notes=Object.entries(errors).filter(([,v])=>v).map(([k])=>({cities:'Meteo delle città non disponibile',hail:'Grandine non disponibile',events:'Catalogo eventi non disponibile',safety:'Bollettino locale non disponibile'}[k]));if(data.hail?.truncated)notes.push('Grandine: campione limitato alle ultime 500 segnalazioni');if(data.hail&&!errors.hail)notes.push(hailRecords(data.hail).length+' osservazioni grandine recenti con posizione; finestra di 2 ore');if(data.events?.truncated)notes.push('Catalogo eventi limitato a 300 record');if(data.safety?.mode==='UNKNOWN')notes.push(data.safety.title);sources.textContent=notes.join(' · ')}
 }
 async function load(force=false){if(!active||document.hidden||busy)return;busy=true;const ticket=run,now=Date.now(),placeKey=localKey(),p=ctx.get().place;
  const jobs=[['hail','atlas/hail-map']];if(force||now-lastModel>(ctx.world?900000:600000)){lastModel=now;jobs.push(['cities',ctx.world?'atlas/world':'atlas/cities'])}if(force||now-lastEvents>900000){lastEvents=now;jobs.push(['events','atlas/events'])};if(force||now-lastSafety>600000||lastPlace!==placeKey)jobs.push(['safety','atmosphere/safety?lat='+p.latitude+'&lon='+p.longitude]);
  paint();await Promise.allSettled(jobs.map(async([kind,path])=>{try{if(ctx.world&&globalThis.navigator?.onLine===false)throw Error('Offline');const value=await ctx.api(path);if(!validSource(kind,value))throw Error('Fonte non leggibile');if(ticket!==run||!active||kind==='safety'&&placeKey!==localKey())return;data[kind]=value;errors[kind]=!!value.stale;if(ctx.world&&['cities','events'].includes(kind)&&num(value.updated))worldCacheWrite(kind,value);const at=Date.now();if(kind==='cities')lastModel=at;if(kind==='events')lastEvents=at;if(kind==='safety'){lastSafety=at;lastPlace=placeKey}}catch{const saved=ctx.world&&['cities','events'].includes(kind)?data[kind]||await worldCacheRead(kind):null;if(ticket===run&&active){data[kind]=saved&&validSource(kind,saved)?{...saved,stale:true}:null;errors[kind]=true}}}));
  if(ticket!==run)return;busy=false;paint();if(active&&localKey()!==placeKey)load();
 }
 function bind(){const select=$('#globe-condition-filter');if(select)select.onchange=()=>{filter=GLOBE_FILTERS.some(([id])=>id===select.value)?select.value:'all';paint()};const refresh=$('[data-conditions-refresh]');if(refresh)refresh.onclick=()=>load(true)}
 function stop(){active=false;run++;busy=false;clearInterval(timer);timer=0;data.hail=null;data.safety=null;lastPlace='';selected=null}
 return {controls,panel,bind,choose,start(){if(active)return;active=true;run++;load();timer=setInterval(()=>{paint();load()},30000)},stop,refresh(){if(!active)return;if(lastPlace!==localKey()){data.safety=null;load()}paint()},rendererError(){const s=$('#globe-conditions-status');if(s)s.textContent='Simboli non disponibili nel renderer. I dati restano consultabili nell’elenco.'}};
}
